import * as vscode from "vscode";

export type ToolbarState = {
  port: string | null;
  fqbn: string | null;
  connectedPorts: string[];
  serverRunning: boolean;
  serverHealthy: boolean;
  lastScanAtMs: number | null;
};

export class ArduinoToolbarViewProvider implements vscode.WebviewViewProvider {
  public static readonly viewType = "arduinoMcp.toolbar";

  private view: vscode.WebviewView | null = null;
  private state: ToolbarState = {
    port: null,
    fqbn: null,
    connectedPorts: [],
    serverRunning: false,
    serverHealthy: false,
    lastScanAtMs: null,
  };

  constructor(private readonly context: vscode.ExtensionContext) {}

  setState(next: ToolbarState) {
    this.state = next;
    this.postState();
  }

  resolveWebviewView(view: vscode.WebviewView) {
    this.view = view;
    view.webview.options = { enableScripts: true };
    view.webview.html = this.html();
    view.webview.onDidReceiveMessage((msg) => void this.onMessage(msg));
    this.postState();
  }

  private postState() {
    this.view?.webview.postMessage({ type: "state", state: this.state });
  }

  private async onMessage(msg: any) {
    if (!msg?.type) return;
    if (msg.type === "cmd") {
      const command = String(msg.command ?? "");
      if (!command) return;
      await vscode.commands.executeCommand(command);
    }
  }

  private html() {
    return `<!doctype html>
<html>
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <style>
      :root{
        --bg:#141414;
        --panel:#242424;
        --panel-2:#2c2c2c;
        --ink:#e8e8e8;
        --soft:#9a9a9a;
        --muted:#7e7e7e;
        --stroke:#3f3f3f;
      }
      body{ margin:0; padding:10px; background:var(--bg); color:var(--ink); font-family: Consolas, Menlo, Monaco, "Courier New", monospace; font-size:11px; }
      .card{ border:2px solid var(--stroke); background:var(--panel); border-radius:10px; padding:10px; box-shadow:4px 4px 0 #000; }
      .promptbox{ border:1px solid var(--stroke); border-radius:8px; background:#1b1b1b; padding:7px 8px; }
      .line{ display:flex; align-items:center; gap:8px; }
      .label{ color:var(--soft); }
      .value{ color:var(--ink); margin-top:2px; margin-bottom:6px; overflow-wrap:anywhere; }
      .ascii{ color:var(--muted); white-space:pre; line-height:1.2; }
      .actions{ display:flex; flex-direction:column; gap:8px; margin-top:10px; }
      .btn{
        display:flex; align-items:center; gap:8px;
        width:100%; min-height:42px;
        padding:8px 9px;
        border-radius:10px;
        border:2px solid var(--stroke);
        background:var(--panel-2);
        color:var(--ink);
        cursor:pointer;
        box-shadow:4px 4px 0 #000;
        font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial;
        font-size:11px;
        font-weight:650;
      }
      .btn:active{ transform: translate(1px,1px); box-shadow:3px 3px 0 #000; }
      .serverbox{ margin-top:10px; border:1px solid var(--stroke); border-radius:8px; background:#1b1b1b; padding:8px; }
      .servertop{ display:flex; align-items:center; justify-content:space-between; }
      .cmdbtn{ color:#e6e6e6; cursor:pointer; position:relative; font-family:Consolas, Menlo, Monaco, "Courier New", monospace; }
      .cmdbtn::after{
        content: attr(data-tip);
        position:absolute;
        left:0;
        bottom:120%;
        background:#0f0f0f;
        color:#f0f0f0;
        border:1px solid #444;
        border-radius:4px;
        padding:2px 5px;
        font-size:11px;
        font-family:Consolas, Menlo, Monaco, "Courier New", monospace;
        opacity:0;
        pointer-events:none;
        transition:opacity .12s ease;
        white-space:nowrap;
      }
      .cmdbtn:hover::after{ opacity:1; }
      .serverline{ margin-top:7px; display:flex; align-items:center; gap:8px; }
      #serverBlock{ font-size:14px; line-height:1; color:#6f6f6f; }
      #serverDots{ color:#ffffff; display:none; }
    </style>
  </head>
  <body>
    <div class="card">
      <div class="promptbox">
        <div class="ascii">+-------------- -  -   -    -     -      -      -  +</div>
        <div class="ascii">| Ports and Boards</div>
        <div class="ascii">+   -   -  - ------------------------------+</div>
        <div class="line"><span class="label">Port:</span><span class="cmdbtn" data-tip="refresh" data-cmd="arduinoMcp.refreshPortsBoards">||R||</span></div>
        <div class="value" id="port">?</div>
        <div class="line"><span class="label">Board:</span></div>
        <div class="value" id="fqbn">?</div>
      </div>

      <div class="actions">
        <button class="btn" data-cmd="arduinoMcp.startSketch">Start Sketch</button>
        <button class="btn" data-cmd="arduinoMcp.upload">Upload</button>
        <button class="btn" data-cmd="arduinoMcp.verify">Verify</button>
        <button class="btn" data-cmd="arduinoMcp.openSerialMonitor">Serial</button>
        <button class="btn" data-cmd="arduinoMcp.openSerialPlotter">Plotter</button>
        <button class="btn" data-cmd="arduinoMcp.openExamples">Examples</button>
        <button class="btn" data-cmd="arduinoMcp.openManagers">Managers</button>
        <button class="btn" data-cmd="arduinoMcp.openBoardTemplate">AI Prompt Template</button>
      </div>

      <div class="serverbox">
        <div class="servertop">
          <span>MCP Server</span>
          <span class="cmdbtn" data-tip="refresh" data-cmd="arduinoMcp.refreshServer">||R||</span>
        </div>
        <div class="serverline"><span id="serverBlock">█</span><span id="serverDots">...</span></div>
      </div>
    </div>

    <script>
      const vscode = acquireVsCodeApi();
      const $ = (id) => document.getElementById(id);
      document.querySelectorAll("[data-cmd]").forEach((el) => {
        const fire = () => vscode.postMessage({ type: "cmd", command: el.getAttribute("data-cmd") });
        el.addEventListener("click", fire);
      });

      function setServer(state) {
        const block = $("serverBlock");
        const dots = $("serverDots");
        dots.style.display = "none";

        if (!state.serverRunning) {
          block.style.color = "#6f6f6f";
          block.textContent = "█";
          return;
        }
        if (state.serverHealthy) {
          block.style.color = "#49c06b";
          block.textContent = "█";
          return;
        }
        block.style.color = "#d2b046";
        block.textContent = "█";
        dots.style.display = "inline";
      }

      window.addEventListener("message", (event) => {
        const msg = event.data;
        if (msg.type !== "state") return;
        const s = msg.state || {};
        $("port").textContent = s.port || "?";
        $("fqbn").textContent = s.fqbn || "?";
        setServer(s);
      });
    </script>
  </body>
</html>`;
  }
}
