import * as vscode from "vscode";
import * as os from "node:os";
import * as path from "node:path";
import * as fs from "node:fs";
import { startBundledServer, type ServerProcess } from "./serverProcess";
import { loadTarget, promptForTarget, refreshBoards, saveTarget, type ArduinoTarget } from "./boards";
import { installCore, runArduinoCli, updateIndexes } from "./arduinoCli";
import { findMainSketchFile, getSketchFolder } from "./sketch";
import { getHealth, setServerBaseUrl } from "./serverHttpClient";
import { SerialMonitorPanel } from "./ui/serialMonitorPanel";
import { SerialPlotterPanel } from "./ui/serialPlotterPanel";
import { ExamplesPanel } from "./ui/examplesPanel";
import { ManagersPanel } from "./ui/managersPanel";
import { BoardTemplatePanel } from "./ui/boardTemplatePanel";
import { ArduinoToolbarViewProvider } from "./views/toolbarView";

const OUTPUT_CHANNEL_NAME = "Arduino Grease";

function delay(ms: number) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export async function activate(context: vscode.ExtensionContext) {
  const output = vscode.window.createOutputChannel(OUTPUT_CHANNEL_NAME);
  context.subscriptions.push(output);

  output.appendLine("Arduino Grease activating...");

  let serverProcess: ServerProcess | null = null;
  let serverHealthy = false;
  let sawServerProblem = false;
  let lastScanAtMs: number | null = null;
  let portsRefreshArmed = false;

  const startServer = async () => {
    if (serverProcess) return true;
    try {
      serverProcess = await startBundledServer(context, output, 3333);
      setServerBaseUrl(`http://127.0.0.1:${serverProcess.port}`);
      output.appendLine(`Arduino Grease server started on port ${serverProcess.port}.`);
      return true;
    } catch (e) {
      output.appendLine(`Failed to start bundled server: ${e instanceof Error ? e.message : String(e)}`);
      return false;
    }
  };

  const stopServer = async () => {
    if (!serverProcess) return;
    await serverProcess.stop();
    serverProcess = null;
    serverHealthy = false;
    sawServerProblem = false;
    output.appendLine("Arduino Grease server stopped.");
  };

  await startServer();

  context.subscriptions.push({
    dispose: () => {
      void stopServer();
    },
  });

  const status = vscode.window.createStatusBarItem(vscode.StatusBarAlignment.Left, 100);
  status.name = "Arduino Grease Target";
  status.command = "arduinoMcp.refreshPortsBoards";
  status.show();
  context.subscriptions.push(status);

  const serialMonitorPanel = new SerialMonitorPanel(output);
  const serialPlotterPanel = new SerialPlotterPanel(output);
  const examplesPanel = new ExamplesPanel(context, output);
  const boardTemplatePanel = new BoardTemplatePanel(context);
  const toolbar = new ArduinoToolbarViewProvider(context);
  context.subscriptions.push(vscode.window.registerWebviewViewProvider(ArduinoToolbarViewProvider.viewType, toolbar));

  let lastCandidates: Awaited<ReturnType<typeof refreshBoards>>["candidates"] = [];
  let lastPorts = new Set<string>();
  let currentTarget: ArduinoTarget | null = await loadTarget(context);

  const refreshToolbarState = () => {
    toolbar.setState({
      port: currentTarget?.port ?? null,
      fqbn: currentTarget?.fqbn ?? null,
      connectedPorts: Array.from(lastPorts),
      serverRunning: serverProcess !== null,
      serverHealthy,
      lastScanAtMs,
    });
  };

  const setWarning = (text: string) => {
    status.text = `$(warning) ${text}`;
    status.backgroundColor = new vscode.ThemeColor("statusBarItem.warningBackground");
    status.tooltip = "Arduino Grease needs a board/port selection";
  };

  const setOk = (target: ArduinoTarget) => {
    if (target.fqbn) {
      status.text = `$(circuit-board) ${target.fqbn} @ ${target.port}`;
      status.backgroundColor = undefined;
      status.tooltip = "Arduino Grease target";
    } else {
      status.text = `$(plug) ${target.port} (board unknown)`;
      status.backgroundColor = new vscode.ThemeColor("statusBarItem.warningBackground");
      status.tooltip = "Port detected but board not resolved";
    }
  };

  const checkServerHealth = async (verbose = false) => {
    if (!serverProcess) {
      serverHealthy = false;
      refreshToolbarState();
      return;
    }

    try {
      const health = await getHealth();
      const ok = Boolean(health.ok && health.name === "arduino-mcp");
      serverHealthy = ok;
      if (!ok) {
        output.appendLine("Problem with MCP Server");
        sawServerProblem = true;
      } else if (sawServerProblem) {
        output.appendLine("MCP Server recovered.");
        sawServerProblem = false;
      }
      if (verbose) {
        output.appendLine(`Server status: ${ok ? "running and healthy" : "running but unhealthy"}`);
      }
    } catch (e) {
      serverHealthy = false;
      output.appendLine("Problem with MCP Server");
      if (verbose) {
        output.appendLine(`Server health check failed: ${e instanceof Error ? e.message : String(e)}`);
      }
      sawServerProblem = true;
    }

    refreshToolbarState();
  };

  const reconcileTarget = async () => {
    lastScanAtMs = Date.now();

    const detection = await refreshBoards(output);
    lastCandidates = detection.candidates;
    const portsNow = new Set(lastCandidates.map((c) => c.port).filter((p): p is string => typeof p === "string"));

    const changed =
      portsNow.size !== lastPorts.size ||
      Array.from(portsNow).some((p) => !lastPorts.has(p)) ||
      Array.from(lastPorts).some((p) => !portsNow.has(p));

    lastPorts = portsNow;

    if (currentTarget?.port && !portsNow.has(currentTarget.port)) {
      output.appendLine(`Port ${currentTarget.port} disconnected. Clearing selected target.`);
      currentTarget = null;
      await saveTarget(context, null);
    }

    const candidatesWithFqbn = lastCandidates.filter((c) => typeof c.fqbn === "string" && typeof c.port === "string");
    const portsOnly = lastCandidates.filter((c) => !c.fqbn && typeof c.port === "string");

    if (!currentTarget && candidatesWithFqbn.length === 1) {
      const only = candidatesWithFqbn[0]!;
      currentTarget = { port: only.port, fqbn: only.fqbn! };
      await saveTarget(context, currentTarget);
    } else if (!currentTarget && candidatesWithFqbn.length === 0 && portsOnly.length === 1) {
      const onlyPort = portsOnly[0]!;
      currentTarget = { port: onlyPort.port, fqbn: null };
      await saveTarget(context, currentTarget);
    }

    // Requested: compare target FQBN against current FQBN at same port every refresh and replace if different.
    if (currentTarget?.port) {
      const samePort = lastCandidates.filter((c) => c.port === currentTarget!.port && typeof c.fqbn === "string");
      if (samePort.length > 0) {
        const detectedFqbn = samePort[0]!.fqbn!;
        if (detectedFqbn && detectedFqbn !== currentTarget.fqbn) {
          currentTarget = { port: currentTarget.port, fqbn: detectedFqbn };
          await saveTarget(context, currentTarget);
          output.appendLine(`Target updated to current port FQBN: ${detectedFqbn}`);
        }
      }
    }

    if (!currentTarget) {
      if (portsNow.size === 0) {
        setWarning("No serial ports detected");
        if (changed) output.appendLine("No Arduino port detected.");
      } else {
        setWarning("Select board/port");
      }
    } else {
      setOk(currentTarget);
      if (changed) {
        output.appendLine(`Port ${currentTarget.port} and Board ${currentTarget.fqbn ?? "unknown"} detected.`);
      }
    }

    refreshToolbarState();
  };

  const refreshPortsAndBoard = async () => {
    output.show(true);
    const detection = await refreshBoards(output);
    lastCandidates = detection.candidates;

    // First preference requested: keep same port and choose detected FQBN on that port.
    if (currentTarget?.port) {
      const samePort = lastCandidates.filter((c) => c.port === currentTarget!.port && typeof c.fqbn === "string");
      if (samePort.length > 0) {
        const chosen = samePort[0]!;
        currentTarget = { port: chosen.port, fqbn: chosen.fqbn! };
        await saveTarget(context, currentTarget);
        setOk(currentTarget);
        refreshToolbarState();
        output.appendLine(`Refreshed target on same port: ${currentTarget.fqbn} @ ${currentTarget.port}`);
        portsRefreshArmed = false;
        return;
      }
    }

    // If already armed, second click should close command palette / quick open.
    if (portsRefreshArmed) {
      await vscode.commands.executeCommand("workbench.action.closeQuickOpen");
      portsRefreshArmed = false;
      return;
    }

    portsRefreshArmed = true;
    setTimeout(() => {
      portsRefreshArmed = false;
    }, 6000);

    const picked = await promptForTarget(context, lastCandidates);
    if (picked) {
      currentTarget = picked;
      setOk(picked);
      refreshToolbarState();
    }
  };

  const getValidSketchPath = async (): Promise<string | null> => {
    const sketchPath = getSketchFolder();
    if (!sketchPath) {
      return null;
    }

    const mainIno = findMainSketchFile(sketchPath);
    if (mainIno) {
      return sketchPath;
    }

    output.appendLine(`Invalid sketch folder (main .ino missing): ${sketchPath}`);
    const choice = await vscode.window.showWarningMessage(
      "Arduino Grease: Current folder is not a valid sketch (missing main .ino).",
      "Start Sketch",
      "Cancel"
    );
    if (choice === "Start Sketch") {
      await vscode.commands.executeCommand("arduinoMcp.startSketch");
    }
    return null;
  };

  const runVerifyOnly = async (fqbnOverride?: string): Promise<{ ok: boolean; sketchPath?: string; fqbn?: string }> => {
    output.show(true);
    const sketchPath = await getValidSketchPath();
    if (!sketchPath) {
      vscode.window.showErrorMessage("Arduino Grease: No valid sketch folder found.");
      return { ok: false };
    }

    const fqbn = fqbnOverride ?? currentTarget?.fqbn ?? null;
    if (!fqbn) {
      const choice = await vscode.window.showWarningMessage(
        "Arduino Grease: Board unknown. Install/select a core so an FQBN is available.",
        "Install core...",
        "Select board/port..."
      );
      if (choice === "Install core...") {
        await vscode.commands.executeCommand("arduinoMcp.installCore");
      } else {
        await vscode.commands.executeCommand("arduinoMcp.refreshPortsBoards");
      }
      return { ok: false };
    }

    const verifyCmd = `$ arduino-cli compile --fqbn ${fqbn} \"${sketchPath}\"`;
    output.appendLine(verifyCmd);

    const res = await runArduinoCli(["compile", "--fqbn", fqbn, sketchPath], sketchPath);
    output.appendLine(res.stdout);
    output.appendLine(res.stderr);

    if (!res.success) {
      vscode.window.showErrorMessage("Arduino Grease: Verify failed (see Output).");
      return { ok: false };
    }

    vscode.window.showInformationMessage("Arduino Grease: Verify succeeded.");
    return { ok: true, sketchPath, fqbn };
  };

  const runUpload = async (opts?: { fqbnOverride?: string; portOverride?: string; verifyFirst?: boolean }) => {
    output.show(true);
    await vscode.workspace.saveAll(false);

    let sketchPath: string | null = null;
    let fqbn: string | null = opts?.fqbnOverride ?? currentTarget?.fqbn ?? null;

    if (opts?.verifyFirst !== false) {
      const verify = await runVerifyOnly(fqbn ?? undefined);
      if (!verify.ok) return;
      sketchPath = verify.sketchPath ?? null;
      fqbn = verify.fqbn ?? fqbn;
    } else {
      sketchPath = await getValidSketchPath();
      if (!sketchPath) return;
    }

    const port = opts?.portOverride ?? currentTarget?.port ?? null;
    if (!port) {
      vscode.window.showWarningMessage("Arduino Grease: Select a port first.");
      await vscode.commands.executeCommand("arduinoMcp.refreshPortsBoards");
      return;
    }
    if (!fqbn || !sketchPath) {
      vscode.window.showWarningMessage("Arduino Grease: Select a board first.");
      await vscode.commands.executeCommand("arduinoMcp.refreshPortsBoards");
      return;
    }

    const uploadCmd = `$ arduino-cli upload -p ${port} --fqbn ${fqbn} \"${sketchPath}\"`;
    output.appendLine(uploadCmd);

    const res = await runArduinoCli(["upload", "-p", port, "--fqbn", fqbn, sketchPath], sketchPath);
    output.appendLine(res.stdout);
    output.appendLine(res.stderr);

    if (!res.success) {
      vscode.window.showErrorMessage("Arduino Grease: Upload failed (see Output).");
    } else {
      vscode.window.showInformationMessage("Arduino Grease: Upload succeeded.");
    }
  };

  const runFirmwareUpload = async (fqbn: string, port: string) => {
    output.show(true);
    const parts = fqbn.split(":");
    const pkg = parts.length >= 2 ? `${parts[0]}:${parts[1]}` : fqbn;

    output.appendLine(`[Mngrs] Downloading/updating core package ${pkg}...`);
    const core = await runArduinoCli(["core", "install", pkg]);
    output.appendLine(core.stdout);
    output.appendLine(core.stderr);

    const tmpRoot = fs.mkdtempSync(path.join(os.tmpdir(), "arduino-grease-fw-"));
    const sketchName = "FirmwareRecovery";
    const sketchDir = path.join(tmpRoot, sketchName);
    fs.mkdirSync(sketchDir, { recursive: true });
    const ino = path.join(sketchDir, `${sketchName}.ino`);
    fs.writeFileSync(
      ino,
      [
        "// Arduino Grease firmware recovery sketch",
        "void setup(){",
        "  pinMode(LED_BUILTIN, OUTPUT);",
        "}",
        "void loop(){",
        "  digitalWrite(LED_BUILTIN, HIGH);",
        "  delay(120);",
        "  digitalWrite(LED_BUILTIN, LOW);",
        "  delay(120);",
        "}",
      ].join("\n"),
      "utf8"
    );

    output.appendLine(`[Mngrs] Compiling recovery firmware for ${fqbn}...`);
    const comp = await runArduinoCli(["compile", "-v", "--fqbn", fqbn, sketchDir], sketchDir);
    output.appendLine(comp.stdout);
    output.appendLine(comp.stderr);
    if (!comp.success) {
      vscode.window.showErrorMessage("Arduino Grease: Firmware compile failed (see Output).");
      return;
    }

    output.appendLine(`[Mngrs] Uploading firmware to ${port}...`);
    const up = await runArduinoCli(["upload", "-v", "-p", port, "--fqbn", fqbn, sketchDir], sketchDir);
    output.appendLine(up.stdout);
    output.appendLine(up.stderr);
    if (!up.success) {
      vscode.window.showErrorMessage("Arduino Grease: Firmware upload failed (see Output).");
      return;
    }

    vscode.window.showInformationMessage("Arduino Grease: Firmware uploaded to target.");
  };

  const managersPanel = new ManagersPanel(context, output, {
    chooseTarget: async (fqbn: string) => {
      const port = currentTarget?.port ?? lastCandidates[0]?.port ?? null;
      if (!port) {
        vscode.window.showWarningMessage("Arduino Grease: No port detected. Connect a board first.");
        return;
      }
      currentTarget = { port, fqbn };
      await saveTarget(context, currentTarget);
      setOk(currentTarget);
      refreshToolbarState();
    },
    uploadFirmwareToTarget: async (fqbn: string) => {
      const port = currentTarget?.port ?? lastCandidates[0]?.port ?? null;
      if (!port) {
        vscode.window.showWarningMessage("Arduino Grease: No port detected. Connect a board first.");
        return;
      }
      currentTarget = { port, fqbn };
      await saveTarget(context, currentTarget);
      setOk(currentTarget);
      refreshToolbarState();
      await runFirmwareUpload(fqbn, port);
    },
  });

  await reconcileTarget();
  await checkServerHealth(true);

  const targetInterval = setInterval(() => {
    void reconcileTarget();
  }, 30_000);
  const healthInterval = setInterval(() => {
    void checkServerHealth(false);
  }, 120_000);
  context.subscriptions.push({ dispose: () => clearInterval(targetInterval) });
  context.subscriptions.push({ dispose: () => clearInterval(healthInterval) });

  context.subscriptions.push(
    vscode.commands.registerCommand("arduinoMcp.serverStatus", async () => {
      output.show(true);
      output.appendLine("Checking MCP server status...");
      if (!serverProcess) {
        output.appendLine("Server status: stopped");
        serverHealthy = false;
        refreshToolbarState();
        return;
      }
      await checkServerHealth(true);
    }),
    vscode.commands.registerCommand("arduinoMcp.refreshServer", async () => {
      output.show(true);
      if (!serverProcess) {
        await startServer();
        await delay(1000);
        await checkServerHealth(true);
        return;
      }

      if (serverProcess && !serverHealthy) {
        await stopServer();
        await delay(1000);
        await startServer();
        await delay(1000);
        await checkServerHealth(true);
        return;
      }

      if (serverProcess && serverHealthy) {
        await stopServer();
        refreshToolbarState();
      }
    }),
    vscode.commands.registerCommand("arduinoMcp.startServer", async () => {
      output.show(true);
      const ok = await startServer();
      if (ok) {
        await checkServerHealth(true);
        output.appendLine("Server start command completed.");
      }
      refreshToolbarState();
    }),
    vscode.commands.registerCommand("arduinoMcp.stopServer", async () => {
      output.show(true);
      await stopServer();
      refreshToolbarState();
    }),
    vscode.commands.registerCommand("arduinoMcp.toggleServer", async () => {
      output.show(true);
      if (serverProcess) {
        await stopServer();
      } else {
        await startServer();
        await checkServerHealth(true);
      }
      refreshToolbarState();
    }),
    vscode.commands.registerCommand("arduinoMcp.startSketch", async () => {
      output.show(true);

      const name = await vscode.window.showInputBox({
        title: "Start new sketch",
        prompt: "Sketch name",
        placeHolder: "BlinkNano33",
        ignoreFocusOut: false,
        validateInput: (value) => {
          const trimmed = value.trim();
          if (!trimmed) return "Sketch name is required.";
          if (!/^[A-Za-z0-9_\-]+$/.test(trimmed)) return "Use only letters, numbers, underscore, or dash.";
          return null;
        },
      });
      if (!name) return;

      const defaultParent = vscode.workspace.workspaceFolders?.[0]?.uri ?? vscode.Uri.file(path.join(os.homedir(), "Documents"));
      const pickedFolder = await vscode.window.showOpenDialog({
        canSelectFiles: false,
        canSelectFolders: true,
        canSelectMany: false,
        defaultUri: defaultParent,
        openLabel: "Create Sketch Here",
        title: "Choose parent folder",
      });
      if (!pickedFolder?.[0]) return;

      const parent = pickedFolder[0].fsPath;
      const sketchPath = path.join(parent, name.trim());

      output.appendLine(`$ arduino-cli sketch new \"${sketchPath}\"`);
      const res = await runArduinoCli(["sketch", "new", sketchPath]);
      output.appendLine(res.stdout);
      output.appendLine(res.stderr);

      if (!res.success) {
        vscode.window.showErrorMessage("Arduino Grease: Failed to create sketch. See output.");
        return;
      }

      const inoPath = path.join(sketchPath, `${name.trim()}.ino`);
      try {
        const doc = await vscode.workspace.openTextDocument(vscode.Uri.file(inoPath));
        await vscode.window.showTextDocument(doc, { preview: false });
      } catch (e) {
        output.appendLine(`Could not open sketch file automatically: ${e instanceof Error ? e.message : String(e)}`);
      }

      output.appendLine(`Sketch created: ${sketchPath}`);
      vscode.window.showInformationMessage(`Arduino Grease: Sketch created (${name.trim()}).`);
    }),
    vscode.commands.registerCommand("arduinoMcp.installCore", async () => {
      output.show(true);
      const items: Array<{ label: string; description: string; pkg: string }> = [
        { label: "Arduino AVR (Uno/Nano/Mega)", description: "arduino:avr", pkg: "arduino:avr" },
        { label: "Arduino SAMD (Nano 33 IoT, MKR)", description: "arduino:samd", pkg: "arduino:samd" },
        { label: "Arduino Mbed OS (Nano 33 BLE, Portenta)", description: "arduino:mbed", pkg: "arduino:mbed" },
        { label: "ESP32", description: "esp32:esp32", pkg: "esp32:esp32" },
        { label: "RP2040", description: "rp2040:rp2040", pkg: "rp2040:rp2040" },
      ];

      const picked = await vscode.window.showQuickPick(items, {
        title: "Install board core",
        placeHolder: "Pick a core package",
        ignoreFocusOut: false,
      });
      if (!picked) return;

      const up = await updateIndexes();
      output.appendLine(up.stdout);
      output.appendLine(up.stderr);

      const res = await installCore(picked.pkg);
      output.appendLine(res.stdout);
      output.appendLine(res.stderr);

      if (!res.success) {
        vscode.window.showErrorMessage(`Arduino Grease: Core install failed for ${picked.pkg}.`);
      } else {
        vscode.window.showInformationMessage(`Arduino Grease: Core installed: ${picked.pkg}.`);
        await reconcileTarget();
      }
    }),
    vscode.commands.registerCommand("arduinoMcp.verify", async () => {
      await runVerifyOnly();
    }),
    vscode.commands.registerCommand("arduinoMcp.upload", async () => {
      await runUpload({ verifyFirst: true });
    }),
    vscode.commands.registerCommand("arduinoMcp.refreshPortsBoards", async () => {
      await refreshPortsAndBoard();
    }),
    vscode.commands.registerCommand("arduinoMcp.selectTarget", async () => {
      await refreshPortsAndBoard();
    }),
    vscode.commands.registerCommand("arduinoMcp.openSerialMonitor", async () => {
      output.show(true);
      const defaultPort = currentTarget?.port ?? lastCandidates[0]?.port ?? null;
      await serialMonitorPanel.start(defaultPort, 9600);
      output.appendLine(
        'Type "baud=X" to set a new baud rate, or try any of the following commands: \'send="Hello World"\', "clear", "disconnect", or "connect". Transmitting from ' +
          `${defaultPort ?? "(unknown port)"}` +
          " below:"
      );
    }),
    vscode.commands.registerCommand("arduinoMcp.serialCommand", async () => {
      output.show(true);
      const command = await vscode.window.showInputBox({
        title: "Serial command",
        prompt: "Enter serial command",
        placeHolder: 'baud=9600 | send="Hello World" | clear | disconnect | connect',
        ignoreFocusOut: false,
      });
      if (!command) return;
      await serialMonitorPanel.handleConsoleCommand(command);
    }),
    vscode.commands.registerCommand("arduinoMcp.openSerialPlotter", async () => {
      output.show(true);
      const defaultPort = currentTarget?.port ?? lastCandidates[0]?.port ?? null;
      serialPlotterPanel.show(defaultPort, true);
      setTimeout(() => {
        void vscode.commands.executeCommand("workbench.action.moveEditorToNewWindow");
      }, 200);
    }),
    vscode.commands.registerCommand("arduinoMcp.openExamples", async () => {
      output.show(true);
      examplesPanel.show(currentTarget?.fqbn ?? null);
    }),
    vscode.commands.registerCommand("arduinoMcp.openManagers", async () => {
      output.show(true);
      managersPanel.show();
    }),
    vscode.commands.registerCommand("arduinoMcp.openBoardTemplate", async () => {
      output.show(true);
      boardTemplatePanel.show({ fqbn: currentTarget?.fqbn ?? null, port: currentTarget?.port ?? null });
    })
  );

  refreshToolbarState();
  output.appendLine("Arduino Grease activated.");
}

export function deactivate() {
  // no-op for now
}
