export type ServerHealth = { ok: boolean; name?: string; port?: number };
export type SerialStatus = { isOpen: boolean; path: string | null; baudRate: number | null; delimiter?: string; bufferedLines?: number };

let baseUrl = "http://127.0.0.1:3333";

export function setServerBaseUrl(url: string) {
  const clean = String(url || "").trim();
  if (!clean) return;
  baseUrl = clean.replace(/\/$/, "");
}

async function postJson<T>(path: string, body: any): Promise<T> {
  const res = await fetch(`${baseUrl}${path}`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(body ?? {}),
  });
  if (!res.ok) throw new Error(`HTTP ${res.status} ${path}`);
  return (await res.json()) as T;
}

export async function getHealth(): Promise<ServerHealth> {
  const res = await fetch(`${baseUrl}/health`);
  if (!res.ok) throw new Error(`HTTP ${res.status} /health`);
  return (await res.json()) as ServerHealth;
}

export async function serialOpen(args: { path: string; baudRate: number }): Promise<{ ok: boolean; serial: SerialStatus }> {
  return postJson("/serial/open", args);
}
export async function serialClose(): Promise<{ ok: boolean; serial: SerialStatus }> {
  return postJson("/serial/close", {});
}
export async function serialWrite(args: { data: string }): Promise<{ ok: boolean }> {
  return postJson("/serial/write", args);
}
export async function serialRead(): Promise<{ ok: boolean; lines: string[]; serial: SerialStatus }> {
  return postJson("/serial/read", {});
}
