import { spawn } from "node:child_process";

export type RunResult = {
  success: boolean;
  exitCode: number | null;
  stdout: string;
  stderr: string;
};

export async function runArduinoCli(args: string[], cwd?: string): Promise<RunResult> {
  const cmd = process.env.ARDUINO_CLI_PATH || "arduino-cli";
  return new Promise((resolve) => {
    const child = spawn(cmd, args, { cwd, env: process.env, shell: false });
    let stdout = "";
    let stderr = "";
    child.stdout.on("data", (d) => (stdout += d.toString()));
    child.stderr.on("data", (d) => (stderr += d.toString()));
    child.on("error", (err) => resolve({ success: false, exitCode: null, stdout, stderr: `${stderr}\n${String(err)}` }));
    child.on("close", (code) => resolve({ success: code === 0, exitCode: code, stdout, stderr }));
  });
}

export async function updateIndexes(): Promise<RunResult> {
  // keep it simple: update boards index (library index is handled in Managers panel)
  return runArduinoCli(["core", "update-index"]);
}

export async function installCore(pkg: string): Promise<RunResult> {
  return runArduinoCli(["core", "install", pkg]);
}

export type BoardCandidate = {
  port: string;
  protocol?: string;
  fqbn?: string;
  name?: string;
};

export async function detectBoardCandidates(): Promise<{ success: boolean; candidates: BoardCandidate[]; raw: string; stderr: string }> {
  const result = await runArduinoCli(["board", "list", "--format", "json"]);
  const raw = result.stdout;
  const stderr = result.stderr;

  if (!result.success) {
    return { success: false, candidates: [], raw, stderr };
  }

  const match = raw.match(/\{[\s\S]*\}\s*$/) || raw.match(/\[[\s\S]*\]\s*$/);
  const jsonStr = match ? match[0] : raw;

  let parsed: any;
  try {
    parsed = JSON.parse(jsonStr);
  } catch (e) {
    return { success: false, candidates: [], raw, stderr: `${stderr}\nFailed to parse JSON: ${e instanceof Error ? e.message : String(e)}` };
  }

  const ports: any[] = Array.isArray(parsed?.detected_ports) ? parsed.detected_ports : [];
  const candidates: BoardCandidate[] = [];

  for (const p of ports) {
    const address = p?.port?.address;
    const protocol = p?.port?.protocol;
    const matching = Array.isArray(p?.matching_boards) ? p.matching_boards : [];

    if (matching.length === 0) {
      if (typeof address === "string") {
        candidates.push({ port: address, protocol });
      }
      continue;
    }

    for (const b of matching) {
      candidates.push({
        port: address,
        protocol,
        fqbn: b?.fqbn,
        name: b?.name,
      });
    }
  }

  return { success: true, candidates, raw, stderr };
}

